字标组合 — 封面用 stacked 主组合，页眉/签名用 horizontal 横排。

```jsx
<Wordmark />                      {/* 主组合 */}
<Wordmark variant="horizontal" /> {/* 页眉 */}
<Wordmark scale={1.6} />          {/* 封面放大 */}
```

tokens.text:
/* 峰值永造局 · 色彩 — 方向 A「界格」
   纪律：纸白为底，墨黑为字，鎏金 ≤4% 仅作点缀，永不大面积铺色。 */
:root {
  /* 基础色 */
  --paper: #FAF7F2;        /* 纸白 — 页面底色 */
  --paper-raised: #FFFFFF; /* 纯白 — 框线内的展示面 */
  --ink: #1A1714;          /* 墨黑 — 标题、字标、强调 */
  --ink-soft: #5C554C;     /* 软墨 — 正文 */
  --stone: #8C857A;        /* 石灰 — 注释、页眉页脚、英文小字 */
  --line: #E5DFD4;         /* 规则线 — 0.5–1px 分区线 */
  --gold: oklch(0.66 0.09 80);      /* 鎏金 — 界格徽记、图形点缀（≈#AF8C4F） */
  --gold-deep: oklch(0.55 0.09 80); /* 深金 — 金色文字专用，保证可读（≈#8F7038） */

  /* 语义别名 */
  --surface-page: var(--paper);
  --surface-card: var(--paper-raised);
  --text-display: var(--ink);
  --text-body: var(--ink-soft);
  --text-caption: var(--stone);
  --text-accent: var(--gold-deep);
  --accent: var(--gold);
  --rule: var(--line);
  --rule-strong: var(--ink);
}

/* 峰值永造局 — webfonts
   中文衬线：思源宋体 Noto Serif SC（标题、字标）
   中文黑体：思源黑体 Noto Sans SC（正文）
   西文与数字：Helvetica Neue（系统字体，无需加载） */
@import url("https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;500;600;700&family=Noto+Sans+SC:wght@300;400;500;700&display=swap");

/* 峰值永造局 · 间距与形态 — 方向 A「界格」
   纪律：无圆角、无阴影；细规则线分区；留白 ≥40%。 */
:root {
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 16px;
  --space-4: 24px;
  --space-5: 40px;
  --space-6: 64px;
  --space-7: 104px;

  --radius: 0px;            /* 永远无圆角 */
  --shadow: none;           /* 永远无阴影 */
  --rule-hairline: 0.5px;   /* 表格内线 */
  --rule-thin: 1px;         /* 标准分区线 */
  --frame-border: 1px solid var(--line); /* 展示框 */

  --page-margin: 64px;      /* 文档页边距 */
  --deck-margin: 96px;      /* 1920 deck 页边距 */
}

/* 峰值永造局 · 字体 — 方向 A「界格」
   中文宋体大字距标题 × 中文黑体细正文 × Helvetica 数字注释 */
:root {
  --font-display: "Noto Serif SC", "Songti SC", serif;
  --font-body: "Noto Sans SC", "PingFang SC", "Helvetica Neue", sans-serif;
  --font-western: "Helvetica Neue", Helvetica, Arial, sans-serif;

  /* 字重 */
  --weight-display: 600;     /* 标题、字标 */
  --weight-display-light: 500;
  --weight-body: 300;        /* 正文细黑 */
  --weight-body-strong: 500;

  /* 字距（中文标题拉开，西文小字大距） */
  --track-wordmark: 0.34em;  /* 字标 峰值永造局 */
  --track-display: 0.08em;   /* 页面标题 */
  --track-kicker: 0.22em;    /* 眉题/KICKER */
  --track-caption: 0.18em;   /* 英文注释小字 */

  /* 字号阶（文档量纲；1920 deck 量纲见 readme） */
  --text-xs: 11px;    /* 页眉页脚、出处 */
  --text-sm: 13px;    /* 注释 */
  --text-base: 16px;  /* 正文 */
  --text-lg: 21px;    /* 小标题 */
  --text-xl: 28px;    /* 章节标题 */
  --text-2xl: 40px;   /* 页面标题 */
  --text-3xl: 64px;   /* 大数字/封面 */

  --leading-body: 1.9;
  --leading-display: 1.35;
}
